Here's a simple C++ program that reads a text file line by line and counts the number of occurrences of a specific word in the file.

```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <sstream>

int main() {
    std::string fileName;
    std::string wordToSearch;
    int wordCount = 0;

    std::cout << "Enter the file name: ";
    std::cin >> fileName;

    std::cout << "Enter the word you want to search for: ";
    std::cin >> wordToSearch;

    std::ifstream inFile(fileName);

    if (!inFile) {
        std::cerr << "Error opening the file " << fileName << std::endl;
        return 1;
    }

    std::string line;
    while (getline(inFile, line)) {
        std::istringstream lineStream(line);
        std::string word;

        while (lineStream >> word) {
            if (word == wordToSearch) {
                wordCount++;
            }
        }
    }

    inFile.close();
    std::cout << "The word \"" << wordToSearch << "\" appears " << wordCount << " times in the file " << fileName << std::endl;

    return 0;
}
```

You can compile and run this program using a C++ compiler like g++:

```
